steps.script:
var dd = tree.root.get_node_or_null("/root/DisembarkDialog")
if dd == null:
	return false
dd.get_ok_button().pressed.emit()
return true

var wb = GameState.get_unit("U_WARBOSS_T")
var m = wb.get("models", [])
if m.is_empty():
	return false
return m[0].get("position", null) != null

var m = tree.root.get_node("Main")
var br = m.get_node("BoardRoot")
var out = []
for nm in ["MoveRangeVisual", "MovementERVisual", "MovementCoherencyVisual"]:
	var n = br.get_node_or_null(nm)
	out.append(-1 if n == null else n.get_child_count())
m.set_meta("overlay_counts", str(out))
return out[2] == 0 and out[0] >= 0 and out[1] > 0

# Carried out of coherency: the single ring must wear its AMBER warning colour
# and agree with the label. Amber, not red - red circles are the enemy
# engagement-range rings and must keep meaning only that.
var m = tree.root.get_node("Main")
var coh = m.get_node("BoardRoot/MovementCoherencyVisual")
if coh.get_child_count() != 1:
	return "expected exactly 1 ring while carrying, got %d" % coh.get_child_count()
var ring = coh.get_node_or_null("CarriedCoherencyRing")
if ring == null:
	return "ring is not named CarriedCoherencyRing"
var lbl = m.get_node_or_null("BoardRoot/MovementGhostVisual/CoherencyStatusLabel")
if lbl == null or not lbl.text.begins_with("Out of coherency"):
	return "expected a broken drop, label said '%s'" % ("<none>" if lbl == null else lbl.text)
var c = ring.default_color
m.set_meta("ring_broken_probe", str(c))
# Amber is high red, mid green, near-zero blue. Cyan (the OK colour) is the
# opposite: low red, high blue. This separates them without pinning exact values.
if c.b > 0.4:
	return "broken drop but ring is still wearing the cyan OK colour: %s" % str(c)
if c.r < 0.7 or c.g < 0.4:
	return "broken-coherency ring is not amber: %s" % str(c)
return "ok"

# Nothing was LOST by deleting the static rings: the P3-116 drag preview is
# the live coherency affordance - a line from the carried ghost to every other
# model in the unit, green when that mate is inside coherency and red when it
# is not, plus a status label riding on the ghost.
var m = tree.root.get_node("Main")
var gv = m.get_node_or_null("BoardRoot/MovementGhostVisual")
if gv == null or gv.get_child_count() == 0:
	return "no ghost"
var ghost = gv.get_child(0)
if not ("coherency_lines_data" in ghost):
	return "ghost has no coherency_lines_data"
var lines = ghost.coherency_lines_data
var lbl = gv.get_node_or_null("CoherencyStatusLabel")
m.set_meta("coh_probe", "lines=%d status=%s label=%s" % [lines.size(), str(ghost.coherency_status_text), "<none>" if lbl == null else lbl.text])
if lines.size() < 9:
	return "only %d coherency lines for a 10-model mob" % lines.size()
var in_range := 0
for l in lines:
	if bool(l.get("in_coherency", false)):
		in_range += 1
if in_range < 1:
	return "no mate reported in coherency"
return "ok"

# The ONE carried-model coherency ring: it exists only while a model is in
# hand, there is exactly one of it (not one per model), it is centred on the
# ghost rather than on the pickup spot, and its radius is the carried base
# radius + the 2" coherency distance.
var m = tree.root.get_node("Main")
var coh = m.get_node("BoardRoot/MovementCoherencyVisual")
if coh.get_child_count() != 1:
	return "expected exactly 1 ring, got %d" % coh.get_child_count()
var ring = coh.get_node_or_null("CarriedCoherencyRing")
if ring == null:
	return "ring is not named CarriedCoherencyRing"
var gv = m.get_node_or_null("BoardRoot/MovementGhostVisual")
if gv == null:
	return "no ghost layer"
if ring.position.distance_to(gv.position) > 1.0:
	return "ring at %s does not track ghost at %s" % [str(ring.position), str(gv.position)]
# Radius back out of the generated points (they are built around the origin).
var r := 0.0
for i in range(ring.get_point_count()):
	r = max(r, ring.get_point_position(i).length())
var want := Measurement.base_radius_px(32) + Measurement.inches_to_px(GameConstants.coherency_distance_inches())
if abs(r - want) > 1.0:
	return "radius %.1f px, expected %.1f px (32mm base + %.1f\") " % [r, want, GameConstants.coherency_distance_inches()]
m.set_meta("ring_probe", "r=%.1f px width=%.1f colour=%s" % [r, ring.width, str(ring.default_color)])
# Thin, and under the ghosts (MOVE_GHOST_Z) so it cannot bury what it guides.
if ring.width > 4.0:
	return "ring stroke %.1f px is too heavy" % ring.width
return "ok"

var m = tree.root.get_node("Main")
var ring = m.get_node("BoardRoot/MovementCoherencyVisual/CarriedCoherencyRing")
var lbl = m.get_node_or_null("BoardRoot/MovementGhostVisual/CoherencyStatusLabel")
var coherent: bool = lbl != null and lbl.text.begins_with("Coherent")
# The drop here keeps the mob coherent, so the ring must be wearing its OK
# colour. Ring, lines and label all read off the same verdict.
if not coherent:
	return "expected a coherent drop, label said '%s'" % ("<none>" if lbl == null else lbl.text)
if ring.default_color.b < 0.5:
	return "coherent drop but ring is not wearing the cyan OK colour: %s" % str(ring.default_color)
return "ok"

var mc = tree.current_scene.movement_controller
var want := 0
for uid in ["U_BOYZ_T", "U_WARBOSS_T"]:
	for m in GameState.get_unit(uid).get("models", []):
		if m.get("alive", true):
			want += 1
if mc.selected_models.size() != want:
	return "selected %d of %d" % [mc.selected_models.size(), want]
if str(mc.selection_mode) != "MULTI":
	return "selection_mode %s" % str(mc.selection_mode)
return "ok"

var md = tree.current_scene.movement_controller.current_phase.get_active_move_data("U_BOYZ_T")
var dists = md.get("model_distances", {})
var missed := []
for uid in ["U_BOYZ_T", "U_WARBOSS_T"]:
	var models = GameState.get_unit(uid).get("models", [])
	for i in range(models.size()):
		if not models[i].get("alive", true):
			continue
		var key = "%s:%s" % [uid, str(models[i].get("id", "m%d" % (i + 1)))]
		if float(dists.get(key, 0.0)) <= 0.5:
			missed.append(key)
if not missed.is_empty():
	return "did not move: %s" % str(missed)
return "ok"

var cl = TutorialManager.checklist_state()
if not bool(cl.get("mob_shifted", false)):
	return "mob_shifted did not tick after the drag"
if bool(cl.get("move_locked", false)):
	return "move_locked ticked before the confirm"
return "ok"

var o = tree.root.get_node("/root/TutorialOverlay")
var t = o.current_checklist_text()
if not t.contains("Lock it in"):
	return "checklist row missing the lock-it-in box: %s" % t
if not t.contains("End This Unit's Move"):
	return "checklist row does not name the button: %s" % t
return "ok"

var pi = PhaseManager.current_phase_instance
var am = pi.active_moves.get("U_BATTLEWAGON_T", {})
return bool(am.get("mode_locked", false))

var d = null
for c in tree.root.get_children():
	if c is Window and c.visible and str(c.name).to_lower().contains("reroll"):
		d = c
if d == null:
	return "NO REROLL DIALOG"
return "%s|%s" % [str(d.name), str(d.has_meta("tutorial_exit_button"))]

# THE BUG / THE FIX. The green dashed ring the player aims at must be drawn at
# the model's REMAINING MOVE, because that is exactly what the drag clamp
# enforces on the model's centre. Before the fix it was drawn at
# remaining + base_extent_px, i.e. ~162px (4.05") further out for this wagon.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var remaining: float = mc._get_effective_move_cap() - mc._get_accumulated_distance()
var want: float = Measurement.inches_to_px(remaining)
var extent: float = Measurement.base_extent_px(mc.selected_model)
m.set_meta("wagon_ring_probe", "ring_radius=%.1fpx remaining=%.2f\" want=%.1fpx base_extent=%.1fpx overdraw=%.2f\"" % [radius, remaining, want, extent, (radius - want) / Measurement.PX_PER_INCH])
return abs(radius - want)

# ...so the held ghost lands exactly ON the ring. THIS is what the player was
# missing: pre-fix the wagon stopped 162px (4.05") inside the dashes with the
# panel already reading Left: 0.00", which is what "the range is much further
# than I'm allowed to drag" looks like from the other side of the screen.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var moved: float = mc.current_path[1].distance_to(mc.drag_start_pos)
m.set_meta("wagon_gap_probe", "ring_radius=%.1fpx ghost_moved=%.1fpx gap=%.2f\"" % [radius, moved, (radius - moved) / Measurement.PX_PER_INCH])
return abs(radius - moved)

# The 'how far can the hull end up' answer the old ring was really drawing is
# still on screen — as the faint MoveHullReach halo, one base extent (4.05"
# for this wagon) outside the dashed ring. That is a hint, not the boundary.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ring = m.get_node("BoardRoot/MoveRangeVisual")
var halo = ring.get_node_or_null("MoveHullReach")
if halo == null:
	return 9999.0
var halo_r: float = halo.points[0].distance_to(mc.drag_start_pos)
var radius: float = ring.get_child(0).points[0].distance_to(mc.drag_start_pos)
var extent: float = Measurement.base_extent_px(mc.selected_model)
m.set_meta("wagon_halo_probe", "halo_radius=%.1fpx ring_radius=%.1fpx gap=%.2f\"" % [halo_r, radius, (halo_r - radius) / Measurement.PX_PER_INCH])
return abs(halo_r - (radius + extent))

# And the label above the ring still reads the MOVE, which now matches the
# circle it labels: 11" of ring for 11" of move.
var ring = tree.root.get_node("Main").get_node("BoardRoot/MoveRangeVisual")
return str(ring.get_child(8).text)
